class Lazy:
    def __init__(self, func):
        self.func = func

    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        if self.name not in obj.__dict__:
            obj.__dict__[self.name] = self.func(obj)
        return obj.__dict__[self.name]

class Data:
    def __init__(self):
        self.calls = 0

    @Lazy
    def total(self):
        self.calls += 1
        return 42

d = Data()
print(d.total)
print(d.total)
print(d.calls)

